package edgeprovision

import (
	"strings"
	"testing"
)

func TestManagerKeyMatchesCompiledWorkerProtocol(t *testing.T) {
	// Generated by importing managerHash from edge/dist/admin-auth.js under Node24.
	const expected = "3b7d23b46095d722c2b91833aae15b1ddba3e26a791b37567dde5cb404a45a6b"
	key := strings.Repeat("A", 43)
	if got := HashManagerKey("edge-contract-fixture", key); got != expected {
		t.Fatalf("Worker credential protocol mismatch: %s", got)
	}
	if HashManagerKey("another-site", key) == expected {
		t.Fatal("manager credential is not site-scoped")
	}
}
